return ['domain'=>'blockstudio','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'ta_LK','project-id-version'=>'Blockstudio','po-revision-date'=>'2026-10-23 15:38+0000','messages'=>['Blockstudio'=>'Blockstudio','The "%1$s" attribute on a %2$s block tag is dropped because the block declares no field with that id. Declare the field, or write it as a data-, aria- or html- attribute to put it on the root element.'=>'%2$s தொகுதி குறிச்சொல்லில் உள்ள "%1$s" பண்புக்கூறு கைவிடப்படுகிறது; ஏனெனில் அந்தத் தொகுதியில் அந்த அடையாளத்துடன் எந்தப் புலமும் அறிவிக்கப்படவில்லை. அந்தப் புலத்தை அறிவிக்கவும் அல்லது மூல உறுப்பில் சேர்க்க data-, aria- அல்லது html- பண்புக்கூறாக எழுதவும்.','This storage key is not declared by the block or its extensions.'=>'இந்தச் சேமிப்பக விசை தொகுதியிலோ அதன் நீட்டிப்புகளிலோ அறிவிக்கப்படவில்லை.','This top-level key is not an attribute of the block, so it is ignored.'=>'இந்த உயர்நிலை விசை தொகுதியின் பண்புக்கூறு அல்ல; எனவே இது புறக்கணிக்கப்படுகிறது.','This key is only read inside the blockstudio object, which is missing.'=>'இந்த விசை blockstudio பொருளுக்குள் மட்டுமே வாசிக்கப்படுகிறது; அந்தப் பொருள் இல்லை.','This value is not among the field options.'=>'இந்த மதிப்பு புலத்திற்கான விருப்பங்களில் இல்லை.','This value has an unsupported shape for the field.'=>'இந்த மதிப்பின் வடிவம் புலத்திற்கு ஆதரிக்கப்படவில்லை.','This repeater has fewer rows than its minimum.'=>'இந்த மீள்பதிவியில் குறைந்தபட்சத்தைவிடக் குறைவான வரிசைகள் உள்ளன.','This repeater has more rows than its maximum.'=>'இந்த மீள்பதிவியில் அதிகபட்சத்தைவிட அதிகமான வரிசைகள் உள்ளன.','This storage key has conflicting field definitions.'=>'இந்தச் சேமிப்பக விசைக்கு முரண்படும் புல வரையறைகள் உள்ளன.','The nested field value overrides this top-level value.'=>'உட்பொதிந்த புல மதிப்பு இந்த மேல்நிலை மதிப்பை மீறுகிறது.','Extension bindings read this value only from blockstudio.attributes.'=>'நீட்டிப்பு பிணைப்புகள் இந்த மதிப்பை blockstudio.attributes இலிருந்து மட்டுமே வாசிக்கும்.','Blockstudio field values must be stored in an object.'=>'Blockstudio புல மதிப்புகள் ஒரு பொருளில் சேமிக்கப்பட வேண்டும்.','Blockstudio is preparing its block cache. Please retry shortly.'=>'Blockstudio அதன் தொகுதி தற்காலிகச் சேமிப்பைத் தயாரிக்கிறது. சிறிது நேரம் கழித்து மீண்டும் முயற்சிக்கவும்.','Canvas is disabled.'=>'Canvas முடக்கப்பட்டுள்ளது.','Invalid or missing CSRF token.'=>'CSRF குறியீடு தவறானது அல்லது இல்லை.','Authentication required.'=>'அங்கீகாரம் தேவை.','Insufficient permissions.'=>'போதுமான அனுமதிகள் இல்லை.','Validation failed.'=>'சரிபார்ப்பு தோல்வியடைந்தது.','Record not found.'=>'பதிவு காணப்படவில்லை.','Invalid islands request.'=>'தீவு கோரிக்கை தவறானது.','Too many islands requested.'=>'அதிகமான தீவுகள் கோரப்பட்டுள்ளன.','Invalid island block.'=>'தீவுத் தொகுதி தவறானது.','Invalid island signature.'=>'தீவு கையொப்பம் தவறானது.','Sorry, you are not allowed to read blocks of this post.'=>'மன்னிக்கவும், இந்தப் பதிவின் தொகுதிகளைப் படிக்க உங்களுக்கு அனுமதி இல்லை.','Sorry, you are not allowed to read blocks as this user.'=>'மன்னிக்கவும், இந்தப் பயனராகத் தொகுதிகளைப் படிக்க உங்களுக்கு அனுமதி இல்லை.','Invalid block.'=>'தொகுதி தவறானது.','Method not allowed.'=>'இந்த முறை அனுமதிக்கப்படவில்லை.','Block not found.'=>'தொகுதி காணப்படவில்லை.','Function not found.'=>'செயல்பாடு காணப்படவில்லை.','Function is not callable.'=>'செயல்பாட்டை அழைக்க முடியாது.','Blockstudio ignored invalid configuration values:'=>'Blockstudio தவறான உள்ளமைவு மதிப்புகளைப் புறக்கணித்தது:','%s: Link text'=>'%s: இணைப்பு உரை','%s: URL'=>'%s: URL','True'=>'சரி','False'=>'தவறு','Could not load database records.'=>'தரவுத்தளப் பதிவுகளை ஏற்ற முடியவில்லை.','This database has no records yet.'=>'இந்தத் தரவுத்தளத்தில் இன்னும் பதிவுகள் இல்லை.','No Blockstudio databases are registered.'=>'Blockstudio தரவுத்தளங்கள் எதுவும் பதிவு செய்யப்படவில்லை.','The selected database could not be found.'=>'தேர்ந்தெடுக்கப்பட்ட தரவுத்தளத்தைக் கண்டறிய முடியவில்லை.','Overview'=>'மேலோட்டம்','Registry'=>'பதிவகம்','Databases'=>'தரவுத்தளங்கள்','Docs'=>'ஆவணங்கள்','No Blockstudio overview 